export function initAutoGrid(selector = '[data-exhuma-auto-grid]', options = {}) {
  const elements = document.querySelectorAll(selector);

  elements.forEach((el) => {
    const minWidth = options.minItemWidth ?? el.dataset.minItemWidth ?? 280;
    const gap = options.gap ?? el.dataset.gap ?? 24;
    const mode = options.mode ?? el.dataset.mode ?? 'auto-fit';
    const maxColumns = options.maxColumns ?? parseInt(el.dataset.maxColumns || '4', 10);
    const alignItems = options.alignItems ?? el.dataset.alignItems ?? 'stretch';

    const minWidthVal = typeof minWidth === 'number' ? `${minWidth}px` : minWidth;
    const gapVal = typeof gap === 'number' ? `${gap}px` : gap;
    const repeatTrack = mode === 'auto-fill' ? 'auto-fill' : 'auto-fit';
    const minTrack = `min(100%, ${minWidthVal})`;

    const cols = maxColumns > 0
      ? `repeat(${repeatTrack}, minmax(max(${minTrack}, calc((100% - ${maxColumns - 1} * ${gapVal}) / ${maxColumns})), 1fr))`
      : `repeat(${repeatTrack}, minmax(${minTrack}, 1fr))`;

    el.style.display = 'grid';
    el.style.gridTemplateColumns = cols;
    el.style.gap = gapVal;
    el.style.alignItems = alignItems;
    el.style.width = '100%';
  });
}

